#!/usr/bin/env python3
"""Plot median predefined-MCP response times from the benchmark CSV generated by `tests/test_mcp_models.py`.

Place in tests/benchmarking/ and run:
    python tests/benchmarking/plot_benchmark_times.py

Output: tests/benchmarking/benchmark_times.png
Bars are medians of OK executions; dots are individual OK executions.
"""

import csv
import math
from collections import defaultdict
from pathlib import Path
from statistics import median

import matplotlib.pyplot as plt
from matplotlib.patches import Patch
from matplotlib.ticker import FuncFormatter

BASE_DIR = Path(__file__).resolve().parent
CSV_FILE = BASE_DIR / "test_mcp_models_results.csv"
PNG_FILE = BASE_DIR / "benchmark_times.png"

TESTS = [
    ("native", "Native"),
    ("combined", "Combined"),
]
MODEL_LABELS = {
    "qwen3.5-397b-a17b": "Qwen 3.5 (397B)",
    "qwen3-coder-next": "Qwen Coder Next",
    "qwen3.6-35b-a3b": "Qwen 3.6 (35B)",
    "deepseek-v4-flash-0731": "DeepSeek V4 Flash",
}


def main():
    if not CSV_FILE.is_file():
        raise FileNotFoundError(f"Missing benchmark file: {CSV_FILE}")

    samples = defaultdict(list)
    attempts = defaultdict(int)
    present_models = set()
    recognized_tests = dict(TESTS)

    with CSV_FILE.open(newline="", encoding="utf-8") as handle:
        for row in csv.DictReader(handle):
            test_id = row.get("test_id", "")
            model = row.get("model", "")
            if test_id not in recognized_tests or not model:
                continue
            present_models.add(model)
            key = (model, test_id)
            attempts[key] += 1
            if row.get("status") != "OK":
                continue
            try:
                seconds = float(row["elapsed_seconds"])
            except (KeyError, TypeError, ValueError):
                continue
            if math.isfinite(seconds) and seconds > 0:
                samples[key].append(seconds)

    models = [m for m in MODEL_LABELS if m in present_models]
    models += sorted(present_models.difference(MODEL_LABELS))
    values = [value for group in samples.values() for value in group]
    if not values:
        raise ValueError("No completed MCP benchmark timings in CSV")

    fig, ax = plt.subplots(figsize=(10.0, 4.8))
    bar_width = 0.78 / len(models)
    model_colors = plt.rcParams["axes.prop_cycle"].by_key()["color"]
    baseline = min(1.0, min(values) * 0.75)

    for mi, model in enumerate(models):
        color = model_colors[mi % len(model_colors)]
        for ti, (test_id, _) in enumerate(TESTS):
            key = (model, test_id)
            group = samples[key]
            x = ti + (mi - (len(models) - 1) / 2) * bar_width
            if not group:
                if attempts[key]:
                    ax.text(x, baseline * 1.25, f"0/{attempts[key]}\nOK",
                            ha="center", va="bottom", fontsize=8)
                continue

            med = median(group)
            ax.bar(x, med - baseline, bottom=baseline,
                   width=bar_width * 0.91, color=color, zorder=2)

            for j, point in enumerate(sorted(group)):
                jitter_step = min(0.025, 0.65 * bar_width / max(1, len(group) - 1))
                jitter = (j - (len(group) - 1) / 2) * jitter_step
                ax.scatter(x + jitter, point, s=23, marker="o",
                           facecolor="white", edgecolor=color,
                           linewidth=1.1, zorder=4)

            ax.annotate(f"{med:.1f}s\n(n={len(group)}/{attempts[key]})",
                        (x, max(group)), xytext=(0, 8),
                        textcoords="offset points", ha="center",
                        va="bottom", fontsize=8, zorder=5)

    ax.set_yscale("log")
    ax.set_ylim(baseline, max(values) * 1.85)
    ticks = [1, 2, 5, 10, 20, 50, 100, 300, 500]
    ax.set_yticks([t for t in ticks if baseline < t < max(values) * 1.85])
    ax.yaxis.set_major_formatter(FuncFormatter(lambda y, pos: f"{y:g}"))
    ax.set_ylabel("Median agent execution time (seconds, log scale)")
    ax.set_xticks(range(len(TESTS)), [label for _, label in TESTS])
    ax.grid(axis="y", which="both", alpha=0.22)
    ax.set_axisbelow(True)

    handles = [
        Patch(facecolor=model_colors[i % len(model_colors)],
              label=MODEL_LABELS.get(model, model))
        for i, model in enumerate(models)
    ]
    ax.legend(handles=handles, loc="upper center", bbox_to_anchor=(0.5, 1.19),
              frameon=False, ncol=min(len(models), 4), fontsize=9)
    fig.tight_layout(pad=1.0)
    fig.savefig(PNG_FILE, dpi=220, bbox_inches="tight")
    plt.close(fig)

    print(f"Saved {PNG_FILE}")
    for test_id, _ in TESTS:
        for model in models:
            total = attempts[model, test_id]
            if not total:
                continue
            group = samples[model, test_id]
            result = f"median={median(group):.1f}s" if group else "no completed timings"
            print(f"  {test_id:<13} {model:<23} {result}; OK={len(group)}/{total}")


if __name__ == "__main__":
    main()
